/**
 * Runs, on `src/api/schema.d.ts` — generated by `make types` from the real
 * pydantic models and held to the tree by `make lint-generated`.
 *
 * `status` and `RunEvent.type` are DERIVED from the generated types rather than
 * restated here. Both are enums on the wire, so the union is the server's own
 * and drift is a compile error rather than a silent disagreement. Deriving is
 * the house pattern — `types/curation.ts` does the same for `ConflictKind`, and
 * its docstring records the drift bug that motivated it.
 *
 * Two narrowings remain, and they ARE frontend assertions rather than
 * guarantees, which is worth being precise about. The backend types `detail` as
 * a bare `str` and `counters` as `dict[str, Any]`. A value outside those unions
 * is not a crash — every consumer either renders the string or falls through a
 * default branch — but nothing warns you at the boundary either. They are kept
 * because they are what make `run.counters.llm_calls` and the pipeline/single
 * split readable; widening `counters` to `Record<string, unknown>` would make
 * every counter site an `as` cast, which is the same assertion with none of the
 * documentation.
 *
 * `ModelMessage` stays fully hand-written: it is the shape inside
 * `RunEvent.data`, which the backend types as `dict[str, Any]`, so there is no
 * generated model to alias onto. It is written by
 * `backend/venona/llm/transcript.py::summarize`.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

/**
 * The six terminal-or-running states, from the wire.
 *
 * `queued` is the one worth knowing: submitted, but its lane was full, and it
 * starts when a slot frees. Contract C11 — the light lane queues rather than
 * refusing, because a lookup someone asked for is still wanted 30 seconds
 * later. Anything treating `queued` as finished reports "nothing found" before
 * the work has begun.
 */
export type RunStatus = Schemas['RunDetail']['status']

/** Contract C11. Served by `GET /api/runs/types`, so adding a run type is one
 *  entry in `backend/venona/services/run_types.py` and no component edit. */
export type RunType = Omit<Schemas['RunTypeOut'], 'detail'> & {
  detail: 'pipeline' | 'single'
}

export type RunTypeList = Omit<Schemas['RunTypeList'], 'types'> & {
  types: RunType[]
}

/**
 * One line of a run's result panel, resolved server-side.
 *
 * The client renders this list without knowing what kind of run it is looking
 * at, which is the whole point: the panel it replaced was written for a lookup
 * and every other single-stage kind fell into it, so a reader's brief reported
 * `sourced: no` on a run that had just written a document. The words belong to
 * `run_types.RunType.facts`; see contract C11.
 */
export type ResolvedFact = Omit<Schemas['ResolvedFact'], 'shape'> & {
  /** Narrowed from the wire's bare `str`, the same assertion `detail` makes
   *  above and for the same reason: it is what lets the renderer switch on a
   *  union rather than cast at every branch. An unknown shape falls through to
   *  the plain-value default. */
  shape: 'count' | 'text' | 'flag' | 'url' | 'link' | 'reader' | 'candidates'
}

/** A run in flight, from `/api/health`. Enough to label it without a second
 *  call. `subject` is what it is about — three rows all reading "Definition
 *  lookup" say less than none. */
export type RunInFlight = Schemas['RunBrief']

/** The nine event types, from the wire. Contract C6 freezes the list, and
 *  `append_event` enforces it, so this is the server's own union. */
export type RunEventType = Schemas['RunEvent']['type']

/** One message from the Claude Code session behind a stage (`model_message`).
 *  Shapes come from `backend/venona/llm/transcript.py::summarize`. Hand-written
 *  because it lives inside `RunEvent.data`, which is untyped on the wire. */
export interface ModelMessage {
  task: string
  kind: 'session_started' | 'text' | 'thinking' | 'tool_use' | 'tool_result' | 'rate_limit'
  text?: string | null
  tool?: string | null
  input?: string | null
  subagent?: boolean
  is_error?: boolean
  chars?: number
  preview?: string
  session_id?: string
  model?: string
  tools?: string[]
  status?: string
  limit_type?: string
  using_overage?: boolean
  blocks?: { kind: string; text?: string; tool?: string; input?: string }[] | null
}

/**
 * INTERSECTED, not `Omit`-ed, and the difference is not cosmetic.
 *
 * The backend model carries `extra="allow"` — contract C6's additive-only rule,
 * so a client on an older build ignores a key it does not know rather than
 * failing on it — which openapi-typescript renders as
 * `{...} & { [key: string]: unknown }`. `Omit` maps over `keyof`, and `keyof`
 * an index signature is `string`, so omitting anything collapses `seq`, `ts`
 * and `stage` to `unknown` along with it. Intersecting narrows `data` — which
 * the backend types as `dict[str, Any]` — and leaves every other declared
 * field intact, `type` included, now that the wire names its own union.
 */
export type RunEvent = Schemas['RunEvent'] & {
  data: Record<string, unknown>
}

/** Frozen counter names (contract C6). */
export interface RunCounters {
  documents_fetched?: number
  documents_new?: number
  clusters?: number
  acronyms_grounded?: number
  acronyms_undefined?: number
  entities_new?: number
  entities_seen?: number
  /** Was missing here while the backend emitted it and `RunsView` labelled it
   *  — the drift that having no generated type for runs allowed. */
  entities_defined?: number
  edges_written?: number
  entities_promoted?: number
  curation_open?: number
  llm_calls?: number
  cost_usd?: number
}

export type RunStage = Schemas['RunStage']

/** One thing a run had to say, at its own level. See `lib/runMessages.ts`. */
export type RunMessage = Schemas['RunMessage']

/**
 * `RunDetail` rather than `RunSummary`, because one frontend type covers both
 * responses: `stages`, `params` and `profile_hash` are optional on it and only
 * `GET /runs/{id}` fills them.
 *
 * `lane`, `label` and `detail` are derived from `kind` by the backend and never
 * stored, so a row written by an older build still describes itself.
 * `hidden_at` records when a run was dropped from the default listing — hiding
 * is reversible and destroys nothing, since `documents`, `assertions` and
 * `sightings` all still carry the run's id.
 */
export type Run = Omit<Schemas['RunDetail'], 'detail' | 'counters' | 'facts'> & {
  detail: 'pipeline' | 'single'
  counters: RunCounters
  facts: ResolvedFact[]
}

/** `hidden` is how many runs the current filter is hiding, surfaced so the
 *  state is never invisible. */
export type RunList = Omit<Schemas['RunList'], 'items'> & {
  items: Run[]
}

/**
 * Run observability. Aliased rather than hand-written for the same reason as
 * the rest of this file: the backend models in `api/schemas/metrics.py` are the
 * source of truth and `make lint-generated` fails on drift.
 *
 * `StageMetrics.metrics` is deliberately left as the generated open map. The
 * backend's `Funnel` names its own drops per stage (`drop_capped`,
 * `drop_outside_window`, …) so a closed union here would have to be edited
 * every time a stage adds a reason — which is exactly the coupling the flat
 * key/value shape exists to avoid.
 */
export type RunMetrics = Schemas['RunMetrics']
export type StageMetrics = Schemas['StageMetrics']
export type SourceStats = Schemas['SourceStats']
export type TaskLatency = Schemas['TaskLatency']

/**
 * `POST /runs` and every other launcher's envelope. Four fields, and `coalesced`
 * is the one the inline `{ run_id: string }` declarations all dropped: a launch
 * that joined an in-flight run rather than starting one is not a failure and not
 * a new run, and a caller that cannot tell them apart reports the wrong thing.
 * Contract C11.
 */
export type RunStarted = Schemas['RunStarted']

/** `POST /runs/hide` — `skipped` counts the runs it would not hide (in flight),
 *  which is why this is not just a number. */
export type RunHideAll = Schemas['RunHideAll']

/** `RunPreview` — what a run would do and cost, before it does it. One shape
 *  for every launch dialog; see `components/runs/RunLaunchDialog.vue`. */
export type RunPreview = Schemas['RunPreview']
